/**
 * @name SQL injection in Snowflake connector
 * @description User input flowing to cursor.execute() without sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection-snowflake
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SnowflakeSqlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to cursor.execute() or similar methods
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("executemany").getACall() or
      call = API::builtin("execute").getACall() or
      // Also look for Snowflake-specific cursor methods
      call = API::moduleImport("snowflake").getMember("connector").getMember("cursor").getMember("execute").getACall() or
      call = API::moduleImport("snowflake").getMember("connector").getMember("cursor").getMember("executemany").getACall()
    |
      sink = call.getArg(0)  // First argument is the SQL query
    )
  }
}

module SnowflakeSqlFlow = TaintTracking::Global<SnowflakeSqlConfig>;
import SnowflakeSqlFlow::PathGraph

from SnowflakeSqlFlow::PathNode source, SnowflakeSqlFlow::PathNode sink
where SnowflakeSqlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

/**
 * @name Unsafe pickle deserialization with user input
 * @description Pickle deserialization with user input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-pickle-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["loads", "load", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleDeserializationFlow = TaintTracking::Global<PickleDeserializationConfig>;
import PickleDeserializationFlow::PathGraph

from PickleDeserializationFlow::PathNode source, PickleDeserializationFlow::PathNode sink
where PickleDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe pickle deserialization with user input from $@.", source.getNode(), "user input"
